target.css:
:root {
  --ink: #30243a;
  --paper: #fffaf2;
  --plum: #69416d;
  --lilac: #eadcf0;
  --gold: #c99038;
  --mist: #eee7dd;
  --line: #d9c9d2;
  --white: #ffffff;
}

.ticket {
  width: 480px;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 16px;
  background: var(--paper);
  color: var(--ink);
}

.ticket-head {
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 14px 16px;
  border-bottom: 1px solid var(--line);
  background: var(--lilac);
}

.ticket-icon {
  display: grid;
  width: 38px;
  height: 38px;
  place-items: center;
  border-radius: 12px;
  background: var(--white);
  font-size: 21px;
}

.ticket-title {
  flex: 1;
}

.ticket-title p,
.ticket-title h1,
.ticket-foot p,
.kit h2 {
  margin: 0;
}

.ticket-title p,
.detail span {
  color: var(--plum);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.8px;
}

.ticket-title h1 {
  margin-top: 2px;
  font-size: 19px;
  line-height: 1.15;
}

.status {
  padding: 5px 8px;
  border-radius: 999px;
  background: var(--gold);
  color: var(--white);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.7px;
}

.details {
  display: grid;
  grid-template-columns: 1.4fr 1fr;
  gap: 8px;
  padding: 12px 16px;
}

.detail {
  display: flex;
  flex-direction: column;
  gap: 3px;
  padding: 9px 10px;
  border-radius: 9px;
  background: var(--mist);
}

.detail strong {
  font-size: 13px;
}

.kit {
  padding: 0 16px 12px;
}

.kit h2 {
  font-size: 13px;
}

.kit-list {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 7px;
  margin: 8px 0 0;
  padding: 0;
  list-style: none;
}

.kit-list li {
  min-height: 58px;
  padding: 8px;
  border: 1px solid var(--line);
  border-radius: 8px;
  font-size: 12px;
  line-height: 1.25;
}

.kit-list b {
  display: block;
  color: var(--gold);
  font-size: 10px;
}

.kit-list em {
  display: block;
  margin-top: 3px;
  color: var(--plum);
  font-size: 11px;
}

.ticket-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 16px;
  border-top: 1px dashed var(--line);
}

.ticket-foot p {
  font-size: 12px;
}

.claim {
  padding: 8px 12px;
  border: 0;
  border-radius: 8px;
  background: var(--plum);
  color: var(--white);
  font-size: 12px;
  font-weight: 800;
}

